CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS demo_students (id text PRIMARY KEY, name text NOT NULL, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS demo_metadata (key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS projects (
 id text PRIMARY KEY, student_id text NOT NULL REFERENCES demo_students(id), name text NOT NULL CHECK(length(name)>0), exam text NOT NULL,
 subjects jsonb NOT NULL DEFAULT '[]', target_date date, description text NOT NULL DEFAULT '', accent text NOT NULL DEFAULT 'blue',
 archived boolean NOT NULL DEFAULT false, pinned boolean NOT NULL DEFAULT false, settings jsonb NOT NULL DEFAULT '{}',
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS conversations (id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,subject text NOT NULL DEFAULT '',sample boolean NOT NULL DEFAULT false,pinned boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS artifacts (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',original_payload jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1 CHECK(revision>0),bookmarked boolean NOT NULL DEFAULT true,conversation_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),FOREIGN KEY(project_id,conversation_id) REFERENCES conversations(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS artifact_revisions(id text PRIMARY KEY,project_id text NOT NULL,artifact_id text NOT NULL,revision integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(artifact_id,revision),FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY,project_id text NOT NULL,conversation_id text NOT NULL,role text NOT NULL CHECK(role IN ('user','assistant','system')),content text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'completed',artifact_id text,context jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,conversation_id) REFERENCES conversations(project_id,id) ON DELETE CASCADE,FOREIGN KEY(project_id,artifact_id) REFERENCES artifacts(project_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS resources (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,type text NOT NULL DEFAULT 'note',subject text NOT NULL DEFAULT '',topic text NOT NULL DEFAULT '',content text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',pinned boolean NOT NULL DEFAULT false,url text,metadata jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,deleted boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS resource_versions (id text PRIMARY KEY,project_id text NOT NULL,resource_id text NOT NULL,version integer NOT NULL,content text NOT NULL DEFAULT '',storage_key text,mime_type text,filename text,byte_size integer CHECK(byte_size>=0),extraction_status text NOT NULL DEFAULT 'completed',extraction_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(resource_id,version),FOREIGN KEY(project_id,resource_id) REFERENCES resources(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS source_chunks (id text PRIMARY KEY,project_id text NOT NULL,resource_id text NOT NULL,version integer NOT NULL,section integer NOT NULL,content text NOT NULL,search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english',content)) STORED,FOREIGN KEY(project_id,resource_id) REFERENCES resources(project_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS source_chunks_search ON source_chunks USING GIN(search_vector);
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,date date NOT NULL,time text NOT NULL DEFAULT '09:00' CHECK(time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),duration integer NOT NULL DEFAULT 30 CHECK(duration BETWEEN 1 AND 1440),subject text NOT NULL DEFAULT '',topic text NOT NULL DEFAULT '',type text NOT NULL DEFAULT 'study',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','in-progress','cancelled')),fixed boolean NOT NULL DEFAULT false,priority integer NOT NULL DEFAULT 2 CHECK(priority BETWEEN 1 AND 3),timezone text NOT NULL DEFAULT 'Australia/Sydney',resource_id text,plan_id text,recurrence jsonb,series_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,resource_id) REFERENCES resources(project_id,id),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS plans (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,status text NOT NULL DEFAULT 'preview',payload jsonb NOT NULL,applied_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
ALTER TABLE tasks DROP CONSTRAINT IF EXISTS tasks_plan_fkey;
ALTER TABLE tasks ADD CONSTRAINT tasks_plan_fkey FOREIGN KEY(project_id,plan_id) REFERENCES plans(project_id,id);
CREATE TABLE IF NOT EXISTS lessons (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,subject text NOT NULL DEFAULT '',topic text NOT NULL DEFAULT '',channel text NOT NULL DEFAULT '',video_id text NOT NULL,duration integer NOT NULL DEFAULT 0 CHECK(duration>=0),position numeric NOT NULL DEFAULT 0 CHECK(position>=0),watched_seconds numeric NOT NULL DEFAULT 0 CHECK(watched_seconds>=0),saved boolean NOT NULL DEFAULT false,completed boolean NOT NULL DEFAULT false,description text NOT NULL DEFAULT '',collection text NOT NULL DEFAULT '',metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS questions (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,subject text NOT NULL,topic text NOT NULL,type text NOT NULL CHECK(type IN ('single','multiple','numerical','free')),prompt text NOT NULL,options jsonb NOT NULL DEFAULT '[]',answer jsonb NOT NULL,explanation text NOT NULL DEFAULT '',hint text NOT NULL DEFAULT '',difficulty text NOT NULL DEFAULT 'Medium',unit text,tolerance numeric,exam_tags jsonb NOT NULL DEFAULT '[]',source text NOT NULL DEFAULT 'Student original',review_status text NOT NULL DEFAULT 'unreviewed',version integer NOT NULL DEFAULT 1,bookmarked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS question_versions (id text PRIMARY KEY,project_id text NOT NULL,question_id text NOT NULL,version integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(question_id,version),FOREIGN KEY(project_id,question_id) REFERENCES questions(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS test_sessions (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,status text NOT NULL DEFAULT 'active',started_at timestamptz NOT NULL DEFAULT now(),deadline timestamptz NOT NULL,submitted_at timestamptz,policy jsonb NOT NULL DEFAULT '{"correct":4,"incorrect":-1,"blank":0}',score numeric,max_score numeric,UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS test_items (id text PRIMARY KEY,project_id text NOT NULL,session_id text NOT NULL,question_id text NOT NULL,position integer NOT NULL,snapshot jsonb NOT NULL,response jsonb,flagged boolean NOT NULL DEFAULT false,UNIQUE(session_id,question_id),FOREIGN KEY(project_id,session_id) REFERENCES test_sessions(project_id,id) ON DELETE CASCADE,FOREIGN KEY(project_id,question_id) REFERENCES questions(project_id,id));
CREATE TABLE IF NOT EXISTS attempts (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,question_id text NOT NULL,question_version integer NOT NULL,question_snapshot jsonb NOT NULL,session_id text,answer jsonb,status text NOT NULL,correct boolean NOT NULL,score numeric NOT NULL,hint_used boolean NOT NULL DEFAULT false,revealed boolean NOT NULL DEFAULT false,elapsed_seconds numeric NOT NULL DEFAULT 0 CHECK(elapsed_seconds>=0),idempotency_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),UNIQUE(project_id,idempotency_key),FOREIGN KEY(project_id,question_id) REFERENCES questions(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES test_sessions(project_id,id));
CREATE TABLE IF NOT EXISTS mistakes (id text PRIMARY KEY,project_id text NOT NULL,attempt_id text NOT NULL,question_id text NOT NULL,category text NOT NULL DEFAULT 'concept',reflection text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'open',next_review date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(attempt_id),FOREIGN KEY(project_id,attempt_id) REFERENCES attempts(project_id,id) ON DELETE CASCADE,FOREIGN KEY(project_id,question_id) REFERENCES questions(project_id,id));
CREATE TABLE IF NOT EXISTS flashcards (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,front text NOT NULL,back text NOT NULL,subject text NOT NULL DEFAULT '',topic text NOT NULL DEFAULT '',deck text NOT NULL DEFAULT 'My flashcards',suspended boolean NOT NULL DEFAULT false,due_date date NOT NULL DEFAULT current_date,interval_days integer NOT NULL DEFAULT 0 CHECK(interval_days>=0),review_count integer NOT NULL DEFAULT 0,last_review timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS review_events (id text PRIMARY KEY,project_id text NOT NULL,card_id text NOT NULL,rating text NOT NULL CHECK(rating IN ('again','hard','good','easy')),rule_version integer NOT NULL DEFAULT 1,interval_days integer NOT NULL,next_due date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,card_id) REFERENCES flashcards(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS focus_sessions (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,elapsed_seconds integer NOT NULL DEFAULT 0 CHECK(elapsed_seconds>=0),title text NOT NULL DEFAULT 'Focus session');
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY,project_id text REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,body text NOT NULL DEFAULT '',href text NOT NULL DEFAULT '/projects',read boolean NOT NULL DEFAULT false,dismissed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learning_events (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,type text NOT NULL,subject text NOT NULL DEFAULT '',reference_id text,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,type text NOT NULL,status text NOT NULL DEFAULT 'queued',error text,payload jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_project_date ON tasks(project_id,date,status);
CREATE INDEX IF NOT EXISTS resources_project_updated ON resources(project_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS conversations_project_updated ON conversations(project_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS messages_conversation_created ON messages(project_id,conversation_id,created_at);
CREATE INDEX IF NOT EXISTS attempts_project_created ON attempts(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS reviews_project_due ON flashcards(project_id,due_date);
